use super::*;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

fn identity_vectors() -> Vec<Value> {
    let fixture: Value =
        serde_json::from_str(include_str!("../../testdata/embedding-identities.json")).unwrap();
    fixture["vectors"].as_array().unwrap().clone()
}

#[test]
fn dimensions_identities_match_plugin_vectors() {
    // These expected ids were generated by the plugin, not by a second copy of
    // the Rust hash recipe. Field order and omission both affect shared rows.
    for vector in identity_vectors() {
        let provider = Provider::from_tiers(
            &json!({"embedding": vector["config"]}),
            &json!({}),
            Path::new("unused"),
        )
        .unwrap();
        assert_eq!(
            provider.model_id(),
            vector["identity"],
            "{}",
            vector["name"]
        );
    }
}

#[test]
fn dimensions_project_override_is_ignored_at_load() {
    let root = tempfile::tempdir().unwrap();
    std::fs::create_dir(root.path().join(".cortexkit")).unwrap();
    let user_path = root.path().join("user.json");
    std::fs::write(
        root.path().join(".cortexkit/magic-context.json"),
        r#"{"embedding":{"dimensions":4096}}"#,
    )
    .unwrap();
    for vector in identity_vectors().into_iter().take(2) {
        std::fs::write(
            &user_path,
            json!({"embedding": vector["config"]}).to_string(),
        )
        .unwrap();
        let settings = crate::config::Loader::with_user_path(user_path.clone()).resolve(
            Some(root.path()),
            "test/model",
            100_000,
        );
        assert_eq!(
            settings.embedding.unwrap().model_id(),
            vector["identity"],
            "{}",
            vector["name"]
        );
    }
}

// The fake reads the complete HTTP body, so assertions cover the wire number
// type and both query and stored-document requests rather than a body builder.
async fn exchange(
    dimensions: Option<Value>,
    response: Value,
    query: bool,
) -> (Value, Option<Vec<Option<Vec<f32>>>>) {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let mut config = json!({"embedding": {
        "provider": "openai-compatible",
        "endpoint": format!("http://{}/v1", listener.local_addr().unwrap()),
        "model": "test-model"
    }});
    if let Some(dimensions) = dimensions {
        config["embedding"]["dimensions"] = dimensions;
    }
    let provider = Provider::from_tiers(&config, &json!({}), Path::new("unused")).unwrap();
    let server = tokio::spawn(async move {
        let (mut socket, _) = listener.accept().await.unwrap();
        let mut bytes = Vec::new();
        let body = loop {
            let mut chunk = [0; 8192];
            let read = socket.read(&mut chunk).await.unwrap();
            assert_ne!(read, 0);
            bytes.extend_from_slice(&chunk[..read]);
            let text = String::from_utf8_lossy(&bytes);
            if let Some(end) = text.find("\r\n\r\n") {
                let length = text[..end]
                    .lines()
                    .find_map(|line| {
                        line.to_ascii_lowercase()
                            .strip_prefix("content-length:")
                            .map(|length| length.trim().parse::<usize>().unwrap())
                    })
                    .unwrap();
                if bytes.len() >= end + 4 + length {
                    break serde_json::from_slice(&bytes[end + 4..end + 4 + length]).unwrap();
                }
            }
        };
        let response = response.to_string();
        socket
            .write_all(
                format!(
                    "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{response}",
                    response.len()
                )
                .as_bytes(),
            )
            .await
            .unwrap();
        body
    });
    let result = if query {
        provider.embed_query("query").await.map(|v| vec![Some(v)])
    } else {
        provider
            .embed_documents(&["first".into(), "second".into()])
            .await
    };
    let body = tokio::time::timeout(Duration::from_secs(2), server)
        .await
        .unwrap()
        .unwrap();
    (body, result)
}

fn response() -> Value {
    json!({"data": [{"embedding": [1, 0]}, {"embedding": [0, 1]}]})
}

#[tokio::test]
async fn dimensions_requests_send_only_configured_integer_width() {
    for query in [false, true] {
        let (body, result) = exchange(Some(json!(2)), response(), query).await;
        assert!(result.is_some());
        assert_eq!(body["dimensions"].as_u64(), Some(2));
        let (body, result) = exchange(None, response(), query).await;
        assert!(result.is_some());
        assert!(body.get("dimensions").is_none());
    }
}

#[tokio::test]
async fn dimensions_invalid_values_are_ignored_like_plugin_recovered_config() {
    // The plugin schema rejects these leaves; its loader recovers the config
    // without them. The Rust tier reader likewise keeps the usable siblings.
    for dimensions in [
        json!(0),
        json!(-768),
        json!(1.5),
        json!(8193),
        json!("768"),
        Value::Null,
    ] {
        let (body, result) = exchange(Some(dimensions.clone()), response(), false).await;
        assert!(result.is_some(), "{dimensions}");
        assert!(body.get("dimensions").is_none(), "{dimensions}");
        let base = identity_vectors().remove(0);
        let mut config = base["config"].clone();
        config["dimensions"] = dimensions;
        let provider = Provider::from_tiers(
            &json!({"embedding": config}),
            &json!({}),
            Path::new("unused"),
        )
        .unwrap();
        assert_eq!(provider.model_id(), base["identity"]);
    }
    let (body, result) = exchange(Some(json!(2.0)), response(), false).await;
    assert!(result.is_some());
    assert_eq!(body["dimensions"].as_u64(), Some(2));
}

#[tokio::test]
async fn dimensions_mismatched_response_rejects_the_whole_batch() {
    // One correct vector must not hide another vector from the endpoint's
    // default subspace under the requested-width identity.
    let mixed = json!({"data": [{"embedding": [1, 0]}, {"embedding": [1, 0, 0]}]});
    let (_, result) = exchange(Some(json!(2)), mixed, false).await;
    assert!(result.is_none());
    let (_, result) = exchange(Some(json!(3)), response(), true).await;
    assert!(result.is_none());
}
